import { code } from '../../code.ts';
import type { AndroidValues } from '../values.ts';

// The path of the file in plugins/android.
export const path = (v: AndroidValues) => `${v.id}/src/main/cpp/CMakeLists.txt`;

export default (v: AndroidValues) => code`
# Generated by plugins/tools/generate.ts from plugins/plugins/${v.id}/plugin.json; do not edit.
cmake_minimum_required(VERSION 3.24)
project(MapLibre${v.product} LANGUAGES CXX)

# Consume only the C header from the SDK AAR, never another copy of mbgl-core.
find_package(MapLibreAndroid REQUIRED CONFIG)
get_filename_component(PLUGIN_ROOT "\${CMAKE_CURRENT_SOURCE_DIR}/${v.pluginRoot}" ABSOLUTE)

add_library(${v.id}-core STATIC
${v.sources})
target_compile_features(${v.id}-core PUBLIC cxx_std_20)
set_target_properties(${v.id}-core PROPERTIES POSITION_INDEPENDENT_CODE ON)
target_include_directories(${v.id}-core PUBLIC
${v.includeDirectories})
target_link_libraries(${v.id}-core PUBLIC MapLibreAndroid::maplibre)

add_library(${v.id} SHARED plugin.cpp)
target_link_libraries(${v.id} PRIVATE ${v.id}-core dl)
`;
